const input = $('When Executed by Another Workflow').first().json;
const row = $input.first().json;

if (!row?.catalog_json) {
  return [{ json: { valid: false, errors: [`No catalog for customer ${input.customer_id}`] } }];
}

const bySku = new Map(JSON.parse(row.catalog_json).map(p => [p.SKU, p]));
const errors = [];

// Consolidate duplicate SKUs so volume tiers apply to the true total
const qtyBySku = new Map();
for (const [i, li] of (input.lineItems ?? []).entries()) {
  if (!bySku.has(li.sku)) { errors.push(`Line ${i + 1}: unknown SKU '${li.sku}'`); continue; }
  if (!Number.isInteger(li.quantity) || li.quantity < 1) { errors.push(`Line ${i + 1}: invalid quantity '${li.quantity}'`); continue; }
  qtyBySku.set(li.sku, (qtyBySku.get(li.sku) ?? 0) + li.quantity);
}
if (!qtyBySku.size && !errors.length) errors.push('Order has no line items');

const line_items = [...qtyBySku].map(([sku, quantity]) => {
  const p = bySku.get(sku);
  const tier = p.Pricing.tiers.find(t => t.up_to === null || quantity <= t.up_to);
  return {
    sku,
    title: p.Title,
    quantity,
    unit_amount_cents: tier.unit_amount_cents,
    line_total_cents: quantity * tier.unit_amount_cents,
    lead_time: p['Lead Time']
  };
});

return [{
  json: {
    valid: errors.length === 0,
    errors,
    currency: 'USD',
    line_items,
    total_cents: line_items.reduce((s, l) => s + l.line_total_cents, 0)
  }
}];
